use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let year = input.as_i64().unwrap();
    let month = input.as_i64().unwrap();
    let days_in_month = match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => {
            if year % 4 == 0 && year % 100 != 0 || year % 400 == 0 {
                29
            } else {
                28
            }
        }
        _ => 0,
    };
    Value::Number(serde_json::Number::from(days_in_month))
}
